# Issue #84: best-effort numeric normalization for a "toNumber" transform —
# finds the first numeric-looking substring and normalizes its decimal
# separator to '.', stripping thousands separators/currency symbols. When
# both '.' and ',' appear, the rightmost one is treated as the decimal point
# (handles both "1.234,56" and "1,234.56"); a single separator appearing more
# than once is treated as a thousands separator and stripped; a single
# separator appearing exactly once is treated as the decimal point (so
# "12,99"/"12.99" both work, at the cost of a genuinely ambiguous
# single-occurrence case like "1.234" always being read as 1.234, never as
# 1234 — chain a regex-extract transform first if that's not what's wanted).
# Empty string if nothing numeric is found.
def _to_number(value):
    match = re.search(r"-?\d[\d.,]*", value)
    if not match:
        return ""
    raw = match.group(0)
    last_dot = raw.rfind(".")
    last_comma = raw.rfind(",")
    if last_dot != -1 and last_comma != -1:
        decimal_pos = max(last_dot, last_comma)
        integer_part = raw[:decimal_pos].replace(".", "").replace(",", "")
        fractional_part = raw[decimal_pos + 1:]
        normalized = f"{integer_part}.{fractional_part}"
    elif raw.count(",") > 1 or raw.count(".") > 1:
        normalized = raw.replace(",", "").replace(".", "")
    else:
        normalized = raw.replace(",", ".")
    try:
        numeric = float(normalized)
    except ValueError:
        return ""
    return str(int(numeric)) if numeric.is_integer() else str(numeric)


# Issue #205: safe, explicit type-conversion transforms -- unlike toNumber's
# best-effort heuristic extraction, these either produce a well-formed value
# or fall back to their own clearly defined "onError" behavior
# ("KeepOriginal" leaves the pre-conversion value untouched, "UseDefault"
# substitutes the transform's own configured "defaultValue") rather than
# silently guessing.
_DATE_FORMAT_TOKEN_PATTERNS = {"yyyy": r"(?P<yyyy>\d{4})", "mm": r"(?P<mm>\d{1,2})", "dd": r"(?P<dd>\d{1,2})"}


def _type_conversion_fallback(value, on_error, default_value):
    return default_value if on_error == "UseDefault" else value


def _to_integer(value, on_error, default_value):
    stripped = value.strip()
    if re.fullmatch(r"[+-]?\d+", stripped):
        return str(int(stripped))
    return _type_conversion_fallback(value, on_error, default_value)


def _to_boolean(value, on_error, default_value):
    normalized = value.strip().lower()
    if normalized in ("true", "1", "yes", "y"):
        return "True"
    if normalized in ("false", "0", "no", "n"):
        return "False"
    return _type_conversion_fallback(value, on_error, default_value)


# source_format is the same "{yyyy}"/"{mm}"/"{dd}" mini-template
# RangeSource.Format (RangeFormat.cs) already uses for ISO week/date
# parameters, compiled into a regex the same way (escape the literal
# template, then substitute each placeholder for its own capture group) so a
# format string valid on the companion side parses identically here. Also
# rejects a structurally-matching but non-existent calendar date (e.g.
# "2026-02-30") via date()'s own ValueError, not just a pattern match.
def _to_date(value, source_format, on_error, default_value):
    pattern = re.escape(source_format)
    for token, token_pattern in _DATE_FORMAT_TOKEN_PATTERNS.items():
        pattern = pattern.replace(re.escape("{" + token + "}"), token_pattern)
    match = re.fullmatch(pattern, value.strip())
    if match:
        try:
            return date(int(match.group("yyyy")), int(match.group("mm")), int(match.group("dd"))).isoformat()
        except ValueError:
            pass
    return _type_conversion_fallback(value, on_error, default_value)


# Issue #234: strict price/currency conversion. number_format is one of
# ToCurrencyTransform.SupportedFormats, each written as its own example
# amount — its first punctuation mark is the thousands separator, its last
# the decimal separator (a space format also accepts no-break/narrow
# no-break spaces, the apostrophe format a typographic apostrophe). Finds
# the first number in the value (a separator only counts when a digit
# follows, so a trailing "." or "," after the amount is never swallowed),
# requires it to match the format strictly (thousands groups of exactly
# three digits, at most one decimal separator), and keeps the fraction
# digits exactly as scraped — no float rounding. Mirrored by
# toCurrencyPreview in extension/popup/field-transforms.js.
_CURRENCY_FORMATS = {
    "1.234,56": (",", "."),
    "1,234.56": (".", ","),
    "1 234,56": (",", "   "),
    "1'234.56": (".", "'’"),
}


def _to_currency(value, number_format, on_error, default_value):
    decimal_sep, thousands_seps = _CURRENCY_FORMATS.get(number_format, _CURRENCY_FORMATS["1.234,56"])
    candidate = re.search(r"[+-]?[0-9](?:[0-9]|[" + re.escape(decimal_sep + thousands_seps) + r"](?=[0-9]))*", value)
    if candidate:
        thousands = "[" + re.escape(thousands_seps) + "]"
        match = re.fullmatch(
            r"([+-]?)([0-9]{1,3}(?:" + thousands + r"[0-9]{3})+|[0-9]+)(?:" + re.escape(decimal_sep) + r"([0-9]+))?",
            candidate.group(0),
        )
        if match:
            integer = str(int(re.sub(thousands, "", match.group(2))))
            sign = "-" if match.group(1) == "-" else ""
            return sign + integer + ("." + match.group(3) if match.group(3) else "")
    return _type_conversion_fallback(value, on_error, default_value)


# Applies a field's ordered transform chain — each step's output feeds the
# next step's input, in the order the user configured them in.
# Issue #206: looks up another field's own already-computed value for
# CombineFieldsTransform/SplitFieldTransform. `siblings` is whatever
# representation the calling shape already has on hand at this point in
# extraction — a plain dict for flat/API-flat mode's in-progress row, or the
# in-construction parent ET.Element for container/API-tree mode (only that
# element's own direct children are considered, i.e. only siblings under the
# very same immediate parent group — see ScrapingPlanValidator's
# ValidateFieldTransformOrdering for why this is guaranteed to already be
# populated for a valid config). Missing/not-yet-computed simply resolves to
# "" rather than raising, the same "don't fail the whole row/element over
# one field" spirit every other transform here already follows.
def _resolve_transform_sibling(siblings, name):
    if siblings is None:
        return ""
    if isinstance(siblings, dict):
        return siblings.get(name, "")
    found = siblings.find(name)
    return (found.text or "") if found is not None else ""


def _apply_transforms(value, transforms, siblings=None):
    for t in transforms:
        kind = t["kind"]
        if kind == "trim":
            value = value.strip()
        elif kind == "regexExtract":
            match = re.search(t["pattern"], value)
            if match:
                try:
                    value = match.group(t.get("group", 0)) or ""
                except (IndexError, re.error):
                    value = ""
            else:
                value = ""
        elif kind == "replace":
            value = value.replace(t["find"], t["replacement"])
        elif kind == "toNumber":
            value = _to_number(value)
        elif kind == "toInteger":
            value = _to_integer(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toBoolean":
            value = _to_boolean(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toDate":
            value = _to_date(value, t.get("sourceFormat", "{yyyy}-{mm}-{dd}"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toCurrency":
            value = _to_currency(value, t.get("format", "1.234,56"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "combineFields":
            value = t.get("separator", " ").join(_resolve_transform_sibling(siblings, n) for n in t.get("sourceFieldNames", []))
        elif kind == "splitField":
            parts = _resolve_transform_sibling(siblings, t.get("sourceFieldName", "")).split(t.get("separator", " "))
            idx = t.get("index", 0)
            value = parts[idx] if 0 <= idx < len(parts) else ""
    return value


def _read_previous_output(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return f.read()
    except FileNotFoundError:
        return None


def _notify_email(diff_text):
    host = os.environ[SMTP_HOST_ENV_VAR]
    port = int(os.environ[SMTP_PORT_ENV_VAR]) if SMTP_PORT_ENV_VAR else 587
    username = os.environ.get(SMTP_USERNAME_ENV_VAR) if SMTP_USERNAME_ENV_VAR else None
    password = os.environ.get(SMTP_PASSWORD_ENV_VAR) if SMTP_PASSWORD_ENV_VAR else None
    sender = os.environ[NOTIFY_EMAIL_FROM_ENV_VAR]
    recipient = os.environ[NOTIFY_EMAIL_TO_ENV_VAR]

    msg = MIMEText(diff_text)
    msg["Subject"] = "Scraping Factory: changes detected"
    msg["From"] = sender
    msg["To"] = recipient

    # EHLO first so has_extn() actually knows what the server advertises —
    # opportunistic STARTTLS (upgrade only if offered) works against both a
    # real provider and an unauthenticated local/internal relay that never
    # advertises it, without needing the caller to say which kind it is.
    with smtplib.SMTP(host, port, timeout=10) as server:
        server.ehlo()
        if server.has_extn("starttls"):
            server.starttls()
            server.ehlo()
        if username and password:
            server.login(username, password)
        server.sendmail(sender, [recipient], msg.as_string())


def _notify_webhook(diff_text):
    url = os.environ[WEBHOOK_URL_ENV_VAR]
    payload = json.dumps({"subject": "Scraping Factory: changes detected", "diff": diff_text}).encode("utf-8")
    req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
    urllib.request.urlopen(req, timeout=10)


# Best-effort: by the time this runs, the current run's own output has
# already been written successfully — a notification failure (unreachable
# SMTP host, webhook down, ...) is reported but never fails the overall run.
def _notify_change(old_content, new_content):
    diff_text = "\n".join(difflib.unified_diff(
        old_content.splitlines(), new_content.splitlines(), fromfile="previous", tofile="current", lineterm="",
    ))
    try:
        if CHANGE_DETECTION_NOTIFY == "Email":
            _notify_email(diff_text)
        else:
            _notify_webhook(diff_text)
    except Exception as e:
        print(f"Warning: change notification failed: {e}")


def _extract_page_rows(soup, base_url):
    # Issue #206 follow-up: a field derived from a combineFields/splitField
    # transform has no selector of its own (SELECTORS[name] == "") — it's
    # excluded from the selector-match zip below and instead computed once
    # per row, in SELECTORS' own declaration order, from whatever sibling
    # values are already in `row` by that point.
    columns = {name: soup.select(sel) for name, sel in SELECTORS.items() if sel}
    n = max((len(v) for v in columns.values()), default=0)

    rows = []
    for i in range(n):
        row = {}
        for name in SELECTORS:
            if name not in columns:
                row[name] = _apply_transforms("", TRANSFORMS.get(name, []), row)
                continue
            elements = columns[name]
            if i < len(elements):
                attr = ATTRIBUTES.get(name)
                raw_value = elements[i].get(attr, "").strip() if attr else elements[i].get_text(strip=True)
                value = _apply_transforms(raw_value, TRANSFORMS.get(name, []), row)
                # Issue #213/#214: replaces the raw URL with its own
                # downloaded local file path — applied AFTER transforms, the
                # same order the container-mode templates already use. Only
                # ever True for an attribute-mode field (validated upstream).
                if attr and DOWNLOAD.get(name) and value:
                    value = _download_resource(value, base_url, MAX_DOWNLOAD_SIZE.get(name), ALLOWED_CONTENT_TYPES.get(name))
                row[name] = value
            else:
                row[name] = ""
        rows.append(row)
    return rows


# Issue #219: a single cheap HEAD request against the primary start URL, run
# before the main extraction phase even starts — a target that hasn't
# changed since the last successful run (same ETag/Last-Modified) or isn't
# reachable at all doesn't need the full cost of a real scrape. Not every
# target reliably sends useful ETag/Last-Modified headers — when neither is
# present (or they differ from the stored value, or there's no stored value
# yet), the check can't tell "changed" from "unchanged" at all, so it
# conservatively falls through to a normal run rather than risk silently
# never updating stale data. Missing/corrupt sidecar (first run ever, or the
# file was deleted) is treated the same as "no previous state yet".
PREFLIGHT_STATE_PATH = OUTPUT_PATH + ".preflight-state.json"
EXIT_PREFLIGHT_UNCHANGED = 4
EXIT_PREFLIGHT_UNREACHABLE = 5


def _read_preflight_state():
    try:
        with open(PREFLIGHT_STATE_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, ValueError, OSError):
        return {}


def _write_preflight_state(etag, last_modified):
    with open(PREFLIGHT_STATE_PATH, "w", encoding="utf-8") as f:
        json.dump({"etag": etag, "lastModified": last_modified}, f)


# Returns (status, etag, last_modified) — status is "unreachable" (the
# request itself failed or came back with an error status), "unchanged" (a
# response header matches the value stored from the last successful run),
# or "proceed" (no comparable header, no previous state yet, or the value
# differs — the main run should go ahead as normal).
def _run_preflight_check(url):
    if not _robots_gate(url):
        return "proceed", None, None
    try:
        _pace_request()
        response = _send_with_retry(lambda _u=url: requests.head(_u, headers=HEADERS, proxies=_proxies_for_requests(), timeout=10, allow_redirects=True), url)
        response.raise_for_status()
    except Exception as e:
        print(f"ERROR: Preflight check failed — target is unreachable: {url} ({e})", file=sys.stderr)
        return "unreachable", None, None

    etag = response.headers.get("ETag")
    last_modified = response.headers.get("Last-Modified")
    previous = _read_preflight_state()
    if etag and previous.get("etag") == etag:
        return "unchanged", etag, last_modified
    if not etag and last_modified and previous.get("lastModified") == last_modified:
        return "unchanged", etag, last_modified
    return "proceed", etag, last_modified




def scrape(url):
    rows = []
    page_number = 1
    page_url = url
    while page_url:
        if page_number > 1 and not _robots_gate(page_url):
            break
        _pace_request()
        response = _checked_request("Request", page_url, lambda: _send_with_retry(lambda _u=page_url: requests.get(_u, headers=HEADERS, proxies=_proxies_for_requests(), timeout=10), page_url))
        _require_ok("Request", page_url, response)
        _BLOCKING_RESPONSES.append({"url": page_url, "final_url": response.url, "length": len(response.content), "text": response.text})
        # Use response.content (bytes) instead of response.text: requests
        # guesses the encoding from the Content-Type header, defaulting to
        # ISO-8859-1 when no charset is given — which mangles UTF-8 pages
        # that only declare their charset via <meta charset>. BeautifulSoup
        # detects that meta tag itself.
        soup = BeautifulSoup(response.content, "html.parser")
        page_rows = _extract_page_rows(soup, response.url)
        if not page_rows:
            break
        rows.extend(page_rows)

        if page_number >= PAGINATION_MAX_PAGES:
            break
        page_number += 1
        next_tag = soup.select_one(PAGINATION_NEXT_LINK_SELECTOR)
        next_href = next_tag.get("href") if next_tag else None
        page_url = urljoin(page_url, next_href) if next_href else None
    return rows


# Issue #319: a failed page request ends in one clean, actionable
# "ERROR: <what> to <url> failed: <detail>" line on stderr and a dedicated
# exit code instead of a raw requests/Playwright traceback — the same shape
# API mode has had since Issue #220 (PythonScriptVerifier.CleanScriptError
# turns such a line into /generate's error text). The hints say what to do
# about the status instead of only repeating it.
EXIT_REQUEST_FAILED = 7


def _request_failed(what, url, detail):
    print(f"ERROR: {what} to {url} failed: {detail}", file=sys.stderr)
    sys.exit(EXIT_REQUEST_FAILED)


def _http_error_detail(status_code):
    if status_code in (401, 403):
        reason = "Unauthorized" if status_code == 401 else "Forbidden"
        return (f"HTTP {status_code} ({reason}). The site refuses this script — it either requires a login "
                f"or blocks automated requests. If a login is needed, use the Browser engine with a login flow "
                f"or send a custom request header (e.g. Cookie or Authorization).")
    if status_code == 404:
        return "HTTP 404 (Not Found). The page doesn't exist (any more) — check the start URL."
    if status_code == 429:
        return ("HTTP 429 (Too Many Requests). The site is rate-limiting this script — enable "
                "\"Pause between requests\" or try again later.")
    if status_code >= 500:
        return (f"HTTP {status_code}. The site's server reported an error — this is usually temporary; "
                f"try again later or enable \"Retry on transient errors\".")
    return f"HTTP {status_code}."


# Runs one requests call; a connection error/timeout becomes a clean error.
# With "Retry on transient errors" enabled, `send` already contains the
# retries, so this only ever reports what is left once they are exhausted.
def _checked_request(what, url, send):
    try:
        return send()
    except requests.RequestException as e:
        _request_failed(what, url, f"could not reach the site ({e.__class__.__name__}).")


def _require_ok(what, url, response):
    if not response.ok:
        _request_failed(what, url, _http_error_detail(response.status_code))

# Issues #228/#333: the one place robots.txt is fetched. Both "honor the
# Crawl-delay" and "check Disallow at run time" read it, so each origin's
# file is requested at most once per run (cached, failures included) — and,
# when a proxy is configured, through it, since a direct request would reveal
# the machine's own address to the target.
import urllib.error
import urllib.parse
import urllib.request

ROBOTS_USER_AGENT = "ScrapingFactory"
ROBOTS_FETCH_USER_AGENT = "Mozilla/5.0 (compatible; ScrapingFactory/1.0; +https://github.com/Aventinis/Scraping-Factory)"
_robots_texts = {}


# Returns (text, problem): (str, None) = the file's content; (None, None) =
# the site has no (readable-by-us) robots.txt — 401/403/404/410, which
# RFC 9309 treats as "no restrictions"; (None, "HTTP 503" | "<ErrorName>") =
# it could not be read, which callers only warn about, never stop on.
def _robots_text(origin):
    if origin in _robots_texts:
        return _robots_texts[origin]
    robots_url = origin + "/robots.txt"
    proxy = _next_proxy()
    handlers = [urllib.request.ProxyHandler({"http": proxy, "https": proxy})] if proxy else []
    opener = urllib.request.build_opener(*handlers)
    request = urllib.request.Request(robots_url, headers={"User-Agent": ROBOTS_FETCH_USER_AGENT})
    try:
        with opener.open(request, timeout=10) as response:
            result = (response.read().decode("utf-8", errors="replace"), None)
    except urllib.error.HTTPError as error:
        result = (None, None) if error.code in (401, 403, 404, 410) else (None, f"HTTP {error.code}")
    except Exception as error:
        result = (None, type(error).__name__)
    _robots_texts[origin] = result
    return result
# Issue #333: checks every request the script is about to make against the
# target's robots.txt Disallow/Allow rules, evaluated at run time — a site may
# have changed its file since the script was generated (and the extension's
# "Check robots.txt" is advisory and runs once). What happens to a disallowed
# request is ROBOTS_ACTION: "Warn" (report, request it anyway), "Skip" (report,
# don't request it, carry on) or "Abort" (report, exit EXIT_ROBOTS_DISALLOWED).
#
# Matching follows RFC 9309, like the extension's own check: the group of the
# "ScrapingFactory" user agent (else "*") applies, the longest matching
# pattern wins, a tie goes to Allow, `*` is a wildcard, a trailing `$` anchors
# the end, and no matching rule means allowed. An unreadable robots.txt (5xx,
# network error) is a warning and never blocks anything; a missing one (4xx)
# means no restrictions.
EXIT_ROBOTS_DISALLOWED = 9
ROBOTS_ACTION = 'Skip'
_robots_rules = {}
_robots_reported = set()


def _robots_pattern_regex(pattern):
    anchored = pattern.endswith("$")
    core = pattern[:-1] if anchored else pattern
    return re.compile(".*".join(re.escape(part) for part in core.split("*")) + ("$" if anchored else ""))


def _parse_robots_rules(text):
    groups = []
    agents = []
    rules = []
    in_rules = False
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].strip()
        field, separator, value = line.partition(":")
        if not separator:
            continue
        field = field.strip().lower()
        value = value.strip()
        if field == "user-agent":
            if in_rules:
                groups.append((agents, rules))
                agents, rules, in_rules = [], [], False
            agents.append(value.split("/")[0].strip().lower())
        elif field in ("allow", "disallow") and agents:
            in_rules = True
            if value:  # an empty Disallow/Allow says nothing
                rules.append((field == "allow", value))
    if agents:
        groups.append((agents, rules))
    own = ROBOTS_USER_AGENT.lower()
    chosen = [group_rules for group_agents, group_rules in groups if own in group_agents]
    if not chosen:
        chosen = [group_rules for group_agents, group_rules in groups if "*" in group_agents]
    return [(allow, _robots_pattern_regex(pattern), len(pattern)) for group_rules in chosen for allow, pattern in group_rules]


def _robots_rules_for(origin):
    if origin not in _robots_rules:
        text, problem = _robots_text(origin)
        if problem:
            print(f"WARNING: could not read {origin}/robots.txt ({problem}) - not enforced for this site.", file=sys.stderr)
        _robots_rules[origin] = _parse_robots_rules(text) if text else []
    return _robots_rules[origin]


def _robots_allowed(url):
    parts = urllib.parse.urlsplit(url)
    if not parts.scheme or not parts.netloc or parts.path == "/robots.txt":
        return True
    target = (parts.path or "/") + ("?" + parts.query if parts.query else "")
    best = None  # (pattern length, allow)
    for allow, regex, length in _robots_rules_for(f"{parts.scheme}://{parts.netloc}"):
        if regex.match(target) and (best is None or length > best[0] or (length == best[0] and allow and not best[1])):
            best = (length, allow)
    return best is None or best[1]


# True = go ahead with this request. Reported once per URL.
def _robots_gate(url):
    if _robots_allowed(url):
        return True
    shown = url
    first_time = shown not in _robots_reported
    _robots_reported.add(shown)
    if ROBOTS_ACTION == "Warn":
        if first_time:
            print(f"WARNING: robots.txt disallows {shown} - requesting it anyway (action: Warn).", file=sys.stderr)
        return True
    if ROBOTS_ACTION == "Skip":
        if first_time:
            print(f"Skipped (disallowed by robots.txt): {shown}")
        return False
    print(f"ERROR: robots.txt disallows {shown} - stopping (action: Abort).", file=sys.stderr)
    sys.exit(EXIT_ROBOTS_DISALLOWED)
# Issue #222: optional pause between outbound requests — a minimum gap
# between the starts of two consecutive requests, drawn uniformly from
# [REQUEST_DELAY_MIN_S, REQUEST_DELAY_MAX_S] each time. Only the part of the
# pause that hasn't already elapsed (e.g. while parsing the previous page) is
# actually slept, and the very first request of a run starts immediately.
# Each pause is announced on stdout — so a long run visibly isn't hanging,
# and so the companion's trial run can tell waiting apart from a stuck
# script (PythonScriptVerifier extends its own deadline by exactly the
# announced pause).
import random
import time

REQUEST_DELAY_MIN_S = 0.5
REQUEST_DELAY_MAX_S = 1.5
_last_request_started_at = None

# Issue #228: the target's own robots.txt can ask for a pace too — a
# `Crawl-delay: N` (seconds between requests) and/or a `Request-rate: R/S`
# (R requests per S seconds, i.e. S/R seconds between requests) directive.
# It is read once, lazily, right before the first pause is computed (for each
# distinct origin of the start URL(s)/API URL), and the larger of that and
# the configured pause above wins. A site that publishes neither is a no-op;
# an unreachable robots.txt only prints a warning, it never stops the run.
# The delay is capped at ROBOTS_DELAY_MAX_S (a typo-sized value would
# otherwise stall the script for hours). Only the generic and the
# "ScrapingFactory" user-agent groups are consulted. When a proxy is
# configured, robots.txt is fetched through it as well — a direct request
# would otherwise reveal the machine's own address to the target.
import urllib.robotparser

ROBOTS_URLS = ['https://example.test/list', 'https://example.test/list?page=2']
ROBOTS_DELAY_MAX_S = 60.0
_robots_delay_s = None


def _robots_origins():
    origins = []
    for raw in ROBOTS_URLS:
        parts = urllib.parse.urlsplit(raw)
        if not parts.scheme or not parts.netloc or "{" in parts.netloc:
            continue
        origin = f"{parts.scheme}://{parts.netloc}"
        if origin not in origins:
            origins.append(origin)
    return origins


def _fetch_robots_delay(origin):
    robots_url = origin + "/robots.txt"
    text, problem = _robots_text(origin)
    if problem:
        print(f"Warning: could not read {robots_url} ({problem}) — no robots.txt delay applied.", file=sys.stderr)
    if text is None:
        return 0.0
    parser = urllib.robotparser.RobotFileParser()
    parser.parse(text.splitlines())
    delay = float(parser.crawl_delay(ROBOTS_USER_AGENT) or 0)
    rate = parser.request_rate(ROBOTS_USER_AGENT)
    if rate is not None and rate.requests > 0:
        delay = max(delay, rate.seconds / rate.requests)
    if delay > 0:
        if delay > ROBOTS_DELAY_MAX_S:
            print(f"Warning: {robots_url} asks for {delay:g} s between requests — capped at {ROBOTS_DELAY_MAX_S:g} s.", file=sys.stderr)
            delay = ROBOTS_DELAY_MAX_S
        print(f"{robots_url} asks for {delay:g} s between requests (Crawl-delay/Request-rate) — honoring it.", flush=True)
    return delay


def _robots_delay():
    global _robots_delay_s
    if _robots_delay_s is None:
        _robots_delay_s = max([_fetch_robots_delay(origin) for origin in _robots_origins()] or [0.0])
    return _robots_delay_s


def _pace_request():
    global _last_request_started_at
    if _last_request_started_at is not None:
        gap = max(random.uniform(REQUEST_DELAY_MIN_S, REQUEST_DELAY_MAX_S), _robots_delay())
        remaining = gap - (time.monotonic() - _last_request_started_at)
        if remaining > 0:
            print(f"Pausing {remaining:.2f} s before the next request (request delay)...", flush=True)
            time.sleep(remaining)
    _last_request_started_at = time.monotonic()


# Issue #223: optional retry with backoff on transient request failures — a
# connection error/timeout, or one of RETRY_ON_STATUS_CODES. Between attempts
# the script waits RETRY_DELAY_S (doubled after every retry when
# RETRY_EXPONENTIAL), or exactly what a 429/503's Retry-After header asks
# for; every wait is capped at RETRY_MAX_WAIT_S. Each retry is announced on
# stdout, so a scheduled run never degrades silently (and so the companion's
# trial run can tell the wait apart from a stuck script). Any other status
# (404/401/403, ...) is returned immediately, and once every attempt has
# failed, the last response is returned / the last error re-raised — exactly
# what the caller would have seen without retries.
import time

RETRY_MAX_ATTEMPTS = 3
RETRY_DELAY_S = 2.0
RETRY_EXPONENTIAL = True
RETRY_MAX_WAIT_S = 60.0
RETRY_ON_STATUS_CODES = {429, 502, 503, 504}


# Connection errors/timeouts of whichever HTTP stacks this script uses:
# requests' own, and Playwright's (navigations and page.context.request).
def _retryable_exceptions():
    found = []
    try:
        import requests as _requests
        found.append(_requests.RequestException)
    except ImportError:
        pass
    try:
        from playwright.sync_api import Error as _PlaywrightError
        found.append(_PlaywrightError)
    except ImportError:
        pass
    return tuple(found)


_RETRYABLE_EXCEPTIONS = _retryable_exceptions()


# Retry-After is either a number of seconds or an HTTP date; anything
# unparseable is ignored in favour of the configured delay.
def _retry_after_seconds(response):
    try:
        headers = {str(k).lower(): v for k, v in dict(getattr(response, "headers", None) or {}).items()}
    except (TypeError, ValueError):
        return None
    value = str(headers.get("retry-after") or "").strip()
    if not value:
        return None
    if value.isdigit():
        return float(value)
    try:
        from datetime import datetime, timezone
        from email.utils import parsedate_to_datetime
        return max(0.0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
    except (TypeError, ValueError, IndexError):
        return None


def _send_with_retry(send, url):
    attempt = 1
    while True:
        try:
            response = send()
            # requests: status_code; Playwright: status (page.goto may also return None)
            status = getattr(response, "status_code", None)
            if status is None:
                status = getattr(response, "status", None)
            if status not in RETRY_ON_STATUS_CODES or attempt >= RETRY_MAX_ATTEMPTS:
                return response
            reason = f"HTTP {status}"
            retry_after = _retry_after_seconds(response) if status in (429, 503) else None
        except _RETRYABLE_EXCEPTIONS as e:
            if attempt >= RETRY_MAX_ATTEMPTS:
                raise
            reason = e.__class__.__name__
            retry_after = None
        wait = retry_after if retry_after is not None else RETRY_DELAY_S * (2 ** (attempt - 1) if RETRY_EXPONENTIAL else 1)
        wait = min(wait, RETRY_MAX_WAIT_S)
        attempt += 1
        print(f"Retrying in {wait:.1f} s (attempt {attempt} of {RETRY_MAX_ATTEMPTS}) after {reason}: {url}", flush=True)
        time.sleep(wait)
        _pace_request()



# Issue #225 (deduplication): see IR/DeduplicationConfig.cs. KEY_FIELDS is
# the (composite) identity of a row/element. Within a run, a later row with
# an already-seen key is dropped. With INCREMENTAL, keys seen in earlier
# runs are remembered in a sidecar file next to the output
# (OUTPUT_PATH + ".dedup-seen.json", key -> unix timestamp of the last time
# it was seen) and only genuinely new rows/elements are written. A row whose
# key fields are all empty has no identity: it is never dropped and never
# remembered (so in incremental mode it is written on every run).
import json as _dd_json
import os as _dd_os
import sys as _dd_sys
import time as _dd_time

DEDUP_KEY_FIELDS = ['Title']
DEDUP_INCREMENTAL = True
DEDUP_RETENTION_KIND = 'MaxCount'
DEDUP_RETENTION_VALUE = 100000
DEDUP_STATE_PATH = OUTPUT_PATH + ".dedup-seen.json"
_dedup_dropped_count = 0


# Bounds the sidecar file: MaxAge forgets keys not seen for N days (they
# count as new again), MaxCount keeps the N most recently seen keys.
def _dedup_prune(seen, now):
    if DEDUP_RETENTION_KIND == "MaxAge":
        cutoff = now - DEDUP_RETENTION_VALUE * 86400
        return {key: stamp for key, stamp in seen.items() if stamp >= cutoff}
    if len(seen) > DEDUP_RETENTION_VALUE:
        newest = sorted(seen.items(), key=lambda item: item[1], reverse=True)[:DEDUP_RETENTION_VALUE]
        return dict(newest)
    return seen


# A missing or unreadable sidecar (first run ever, or it was deleted) simply
# means "nothing seen yet" — never an error.
def _dedup_load_state():
    if not DEDUP_INCREMENTAL:
        return {}
    try:
        with open(DEDUP_STATE_PATH, "r", encoding="utf-8") as f:
            raw = _dd_json.load(f).get("seen", {})
        seen = {str(key): float(stamp) for key, stamp in raw.items()}
    except (OSError, ValueError, AttributeError, TypeError):
        return {}
    return _dedup_prune(seen, _dd_time.time())


_DEDUP_SEEN = _dedup_load_state()


# Records every key of this run as seen "now" and writes the sidecar. Called
# from main() only once the run is otherwise done (after hardening's own
# pass/fail decision), so a run that is about to be flagged as failed never
# marks its rows as seen — the next run would otherwise silently skip them.
def _dedup_save_state(current_keys):
    if not DEDUP_INCREMENTAL:
        return
    now = _dd_time.time()
    seen = dict(_DEDUP_SEEN)
    for key in current_keys:
        seen[key] = now
    seen = _dedup_prune(seen, now)
    with open(DEDUP_STATE_PATH, "w", encoding="utf-8") as f:
        _dd_json.dump({"seen": seen}, f, ensure_ascii=False)


def _dedup_key(values):
    if all(not value for value in values):
        return None
    return _dd_json.dumps(values, ensure_ascii=False)

# Flat shape: drops later rows whose key already appeared in this run.
# Returns the unique rows plus a parallel list of their keys (None for a row
# without any key value).
def _dedup_filter_rows(rows):
    global _dedup_dropped_count
    seen_in_run = set()
    unique_rows = []
    keys = []
    for row in rows:
        key = _dedup_key([str(row.get(name, "") or "").strip() for name in DEDUP_KEY_FIELDS])
        if key is not None:
            if key in seen_in_run:
                _dedup_dropped_count += 1
                continue
            seen_in_run.add(key)
        unique_rows.append(row)
        keys.append(key)
    if _dedup_dropped_count:
        print(f"Deduplication: dropped {_dedup_dropped_count} duplicate row(s).")
    return unique_rows, keys


# Incremental mode: only the rows whose key was not seen in an earlier run.
def _dedup_new_rows(rows, keys):
    if not DEDUP_INCREMENTAL:
        return rows
    new_rows = [row for row, key in zip(rows, keys) if key is None or key not in _DEDUP_SEEN]
    print(f"Deduplication: {len(new_rows)} of {len(rows)} row(s) are new since the last run.")
    return new_rows



# Issue #342: append this run's result to the existing output file instead of
# replacing it. One rule for schema drift in every format: whatever columns/
# fields the file already has are kept, new ones are added, and a value that
# is missing on either side is empty. An existing file that cannot be read or
# has a different shape (e.g. a JSON object where a list is expected) stops
# the run with a clear message — silently overwriting accumulated data would
# be worse. A missing or empty file is simply the first run. (CSV/JSON/XML
# are merged here before the normal writer runs; SQLite/Excel append inside
# their own writers, see output_tabular.)
import csv as _ap_csv
import json as _ap_json
import os as _ap_os

EXIT_APPEND_FAILED = 10


def _append_failed(path, reason):
    print(f"ERROR: cannot append to {path}: {reason}", file=sys.stderr)
    sys.exit(EXIT_APPEND_FAILED)


def _merge_fieldnames(existing, new):
    return list(existing) + [name for name in new if name not in existing]


# Flat CSV / JSON array: previous rows first, then this run's; the columns are
# the file's own plus any new ones. Returns (fieldnames, rows).
def _append_previous_rows(path, fieldnames, rows):
    if not _ap_os.path.exists(path) or _ap_os.path.getsize(path) == 0:
        return fieldnames, rows
    try:
        with open(path, "r", encoding="utf-8", newline="") as f:
            if path.lower().endswith(".json"):
                previous = _ap_json.load(f)
                if not isinstance(previous, list) or not all(isinstance(item, dict) for item in previous):
                    _append_failed(path, "the existing file is not a JSON list of records.")
                columns = []
                for item in previous:
                    columns = _merge_fieldnames(columns, item.keys())
                return _merge_fieldnames(columns, fieldnames), previous + rows
            reader = _ap_csv.DictReader(f)
            previous = list(reader)
            columns = list(reader.fieldnames or [])
    except (OSError, ValueError, _ap_csv.Error) as error:
        _append_failed(path, f"the existing file could not be read ({type(error).__name__}).")
    merged = _merge_fieldnames(columns, fieldnames)
    return merged, [{name: row.get(name) or "" for name in merged} for row in previous + rows]


# XML: this run's children are appended under the existing root element.
# Returns the root to write — the existing one, extended.
def _append_previous_xml(path, root):
    import xml.etree.ElementTree as _ap_et
    if not _ap_os.path.exists(path) or _ap_os.path.getsize(path) == 0:
        return root
    try:
        existing = _ap_et.parse(path).getroot()
    except (OSError, _ap_et.ParseError) as error:
        _append_failed(path, f"the existing file could not be read ({type(error).__name__}).")
    if existing.tag != root.tag:
        _append_failed(path, f"its root element <{existing.tag}> is not <{root.tag}>.")
    for child in list(root):
        existing.append(child)
    return existing


# JSON tree (an object of tag -> value | list, see _xml_to_dict): a tag that
# occurs in both becomes one list of all occurrences, new tags are added.
def _append_previous_json_tree(path, tree):
    if not _ap_os.path.exists(path) or _ap_os.path.getsize(path) == 0:
        return tree
    try:
        with open(path, "r", encoding="utf-8") as f:
            existing = _ap_json.load(f)
    except (OSError, ValueError) as error:
        _append_failed(path, f"the existing file could not be read ({type(error).__name__}).")
    if not isinstance(existing, dict):
        _append_failed(path, "the existing file is not a JSON object.")
    merged = dict(existing)
    for key, value in tree.items():
        if key in merged:
            old = merged[key] if isinstance(merged[key], list) else [merged[key]]
            merged[key] = old + (value if isinstance(value, list) else [value])
        else:
            merged[key] = value
    return merged


def main():
    preflight_status, preflight_etag, preflight_last_modified = _run_preflight_check(URLS[0])
    if preflight_status == "unreachable":
        sys.exit(EXIT_PREFLIGHT_UNREACHABLE)
    if preflight_status == "unchanged":
        print("Preflight check: no change detected since the last run — skipping.")
        sys.exit(EXIT_PREFLIGHT_UNCHANGED)
    previous_content = _read_previous_output(OUTPUT_PATH)
    all_urls = URLS
    data = []
    for url in all_urls:
        if not _robots_gate(url):
            continue
        data.extend(scrape(url))
    data, required_fields_failed = _filter_required_fields(data)
    data, dedup_keys = _dedup_filter_rows(data)
    written_data = _dedup_new_rows(data, dedup_keys)
    # Issue #191: BLUEPRINT_MAPPING, when set, takes over the write-time
    # remap entirely instead of FIELD_OUTPUT_NAMES — it already fully
    # determines the output's column names *and* order, and any source
    # field with no entry in it is dropped rather than written under its
    # own name. Issue #178: otherwise, a no-op remap when no field was
    # renamed via the external config (FIELD_OUTPUT_NAMES is then empty) —
    # `data` itself stays keyed by the original field names throughout
    # either way, since hardening/change detection below still need to look
    # fields up by those original names.
    if BLUEPRINT_MAPPING:
        output_rows = [{m["target"]: row.get(m["source"], "") for m in BLUEPRINT_MAPPING} for row in written_data]
        output_fieldnames = [m["target"] for m in BLUEPRINT_MAPPING]
    else:
        # Issue #206 follow-up: a HiddenFromOutput field is dropped here —
        # at the write-time projection only, same as FIELD_OUTPUT_NAMES —
        # never from `data` itself, which hardening/change detection (and
        # any combineFields/splitField transform referencing it) still need
        # to see under its real name.
        output_rows = [
            {FIELD_OUTPUT_NAMES.get(k, k): v for k, v in row.items() if k not in HIDDEN_FIELD_NAMES}
            for row in written_data
        ]
        output_fieldnames = [FIELD_OUTPUT_NAMES.get(name, name) for name in SELECTORS.keys() if name not in HIDDEN_FIELD_NAMES]
    appended_count = len(output_rows)
    output_fieldnames, output_rows = _append_previous_rows(OUTPUT_PATH, output_fieldnames, output_rows)
    with open(OUTPUT_PATH, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=output_fieldnames)
        writer.writeheader()
        writer.writerows(output_rows)
    print(f"Done — {appended_count} rows appended to {OUTPUT_PATH}")
    with open(OUTPUT_PATH, "r", encoding="utf-8") as f:
        new_content = f.read()
    if previous_content is not None and previous_content != new_content:
        _notify_change(previous_content, new_content)
    hardening_failed = _run_hardening_checks(data) or required_fields_failed
    if not hardening_failed:
        _write_baseline(len(data))
    if hardening_failed:
        sys.exit(EXIT_HARDENING_FAILED)
    # Only reached if hardening (when enabled) didn't just sys.exit() above —
    # a run that's about to be flagged as hardening-failed must never
    # advance the preflight state, same "don't let a bad run become the new
    # normal" rule BaselineCheck's own write already follows.
    _write_preflight_state(preflight_etag, preflight_last_modified)
    _dedup_save_state([key for key in dedup_keys if key is not None])
    if _PROXY_ENV_MISSING:
        sys.exit(EXIT_MISSING_ENV_VAR)


if __name__ == "__main__":
    main()
